/**
 * components/shared/pdf/Form1099NEC.js - 1099-NEC per creator.
 *
 * Substitute (printable) Nonemployee Compensation form, three pages: Copy A
 * (filer), Copy B (recipient), Copy C (payer record). The actual IRS filing is
 * done manually via the IRIS portal; this PDF is the substitute the contractor
 * receives.
 *
 * Used by: TaxCenter (Financials > Tax Center).
 *
 * @perf lazy-load only (heavy @react-pdf/renderer); never import at top level.
 * @security recipient TIN (payeeInfo.tax_id) is printed here; it reaches the PDF
 *           only via the audit-logged get_profile_tax_id path. @see docs/MONEY.md (tax)
 */
import React from 'react';
import { Document, Page, Text, View, StyleSheet } from '@react-pdf/renderer';
import { formatTaxAmount } from '../../../utils/ledger-tax';
import { PRINT } from '../../../utils/printPalette';

const P = { ...PRINT, light: PRINT.lightRule };

const s = StyleSheet.create({
  page:      { padding: 36, fontFamily: 'Helvetica', fontSize: 9, color: P.nearBlack, backgroundColor: P.warmWhite },
  copyTag:   { fontSize: 9, color: P.muted, marginBottom: 8, textTransform: 'uppercase', letterSpacing: 2 },
  formNum:   { fontSize: 22, fontWeight: 700 },
  formName:  { fontSize: 11, color: P.muted, marginBottom: 10 },
  yearTag:   { fontSize: 28, color: P.orange, fontWeight: 700, position: 'absolute', right: 36, top: 36 },
  twoCol:    { flexDirection: 'row', gap: 12, marginTop: 4 },
  col:       { flex: 1, borderWidth: 0.5, borderColor: P.rule, borderStyle: 'solid', padding: 10 },
  partyL:    { fontSize: 8, color: P.muted, textTransform: 'uppercase', letterSpacing: 1 },
  partyV:    { fontSize: 10, marginTop: 2 },
  boxRow:    { marginTop: 12, borderWidth: 0.5, borderColor: P.rule, borderStyle: 'solid', padding: 10, flexDirection: 'row', alignItems: 'center' },
  boxLabel:  { fontSize: 8, color: P.muted, textTransform: 'uppercase', letterSpacing: 1 },
  boxName:   { fontSize: 10, marginTop: 2, flex: 1 },
  boxValue:  { fontSize: 18, color: P.orange, fontWeight: 700, width: 160, textAlign: 'right' },
  notice:    { marginTop: 18, fontSize: 8.5, color: P.muted, lineHeight: 1.4 },
  footer:    { position: 'absolute', bottom: 18, left: 36, right: 36, textAlign: 'center', fontSize: 8, color: P.muted, letterSpacing: 1 },
});

const COPIES = [
  { code: 'A', label: 'Copy A: For Internal Revenue Service Center' },
  { code: 'B', label: 'Copy B: For Recipient' },
  { code: 'C', label: 'Copy C: For Payer' },
];

function PartyBox({ label, info }) {
  const cityLine = [info.city, info.state_province, info.postal_code].filter(Boolean).join(', ');
  return (
    <View style={s.col}>
      <Text style={s.partyL}>{label}</Text>
      <Text style={s.partyV}>{info.legal_name || info.full_name || ''}</Text>
      <Text style={s.partyV}>{info.street_address || ''}</Text>
      <Text style={s.partyV}>{cityLine}</Text>
      {info.contact_phone ? <Text style={s.partyV}>{info.contact_phone}</Text> : null}
      <Text style={[s.partyL, { marginTop: 6 }]}>TIN / EIN</Text>
      <Text style={s.partyV}>{info.tax_id || info.ein || '—'}</Text>
    </View>
  );
}

function CopyPage({ form, copy }) {
  return (
    <Page size="LETTER" style={s.page}>
      <Text style={s.copyTag}>{copy.label}</Text>
      <Text style={s.yearTag}>{form.fiscalYear}</Text>
      <Text style={s.formNum}>Form 1099-NEC</Text>
      <Text style={s.formName}>Nonemployee Compensation</Text>

      <View style={s.twoCol}>
        <PartyBox label="Payer" info={form.payerInfo} />
        <PartyBox label="Recipient" info={form.payeeInfo} />
      </View>

      <View style={s.boxRow}>
        <View style={{ flex: 1 }}>
          <Text style={s.boxLabel}>Box 1</Text>
          <Text style={s.boxName}>Nonemployee compensation</Text>
        </View>
        <Text style={s.boxValue}>${formatTaxAmount(form.box1)}</Text>
      </View>

      <Text style={s.notice}>
        This is important tax information and is being furnished to the IRS. If you are
        required to file a return, a negligence penalty or other sanction may be imposed
        on you if this income is taxable and the IRS determines that it has not been reported.
      </Text>

      <Text style={s.footer}>Form 1099-NEC · FY {form.fiscalYear} · Generated from Nysterys ledger</Text>
    </Page>
  );
}

/**
 * The three-copy 1099-NEC document.
 * @param {object} props
 * @param {object} props.form - { fiscalYear, payerInfo, payeeInfo, box1 }; renders null when absent.
 */
export default function Form1099NECDocument({ form }) {
  if (!form) return null;
  return (
    <Document>
      {COPIES.map((c) => (<CopyPage key={c.code} form={form} copy={c} />))}
    </Document>
  );
}
